P=np.array([[5,0,0],[0,5,0],[0,0,0]])
def gen(P,H,W,cross):
 out=np.zeros((H,W),int)
 for r in range(H):
  for c in range(W):
   if P[r%P.shape[0],c%P.shape[1]]:
    out[r,c]=P[r//P.shape[0]%P.shape[0],c//P.shape[1]%P.shape[1]] or cross
 return out
res=gen(P,10,15,4).tolist()
